Object.assign(SNIP,{"l31dtor": "class MangDong {\n    int* a;\n    int n;\npublic:\n    MangDong(int k) : a(new int[k]), n(k) {}     // xin bộ nhớ khi sinh ra\n    ~MangDong() { delete[] a; }                  // trả bộ nhớ khi chết\n};\nvoid f() {\n    MangDong m(1000);   // hàm tạo chạy ở đây\n    // ... dùng m ...\n}                       // hết phạm vi: hàm hủy tự chạy, không cần nhớ delete", "l31ctor": "class PhanSo {\n    int tu, mau;\npublic:\n    PhanSo() : tu(0), mau(1) {}                  // hàm tạo mặc định\n    PhanSo(int t, int m) : tu(t), mau(m) {       // danh sách khởi tạo sau dấu :\n        if (mau == 0) mau = 1;                   // thân hàm: kiểm tra, chuẩn hóa\n        if (mau < 0) { tu = -tu; mau = -mau; }\n    }\n};\nPhanSo a;          // gọi PhanSo()\nPhanSo b(3, -4);   // gọi PhanSo(int, int): b là -3/4\nPhanSo c{1, 2};    // cũng gọi PhanSo(int, int)"});PRESET_NOTES["l31"]={"Ví dụ: Hàm tạo bảo đảm đối tượng hợp lệ": "Mỗi khai báo gọi một hàm tạo: a dùng PhanSo(), b và c dùng PhanSo(int, int). Phần sau dấu : gán tu, mau trước; thân hàm sửa mẫu âm và mẫu bằng 0. Không cách nào tạo ra một PhanSo có mẫu bằng 0.", "Ví dụ: Thứ tự gọi hàm tạo và hàm hủy": "b, c được tạo theo thứ tự và hủy ngược lại (san trước, bep sau) ngay tại dấu } của khối. d được tạo và hủy trong từng vòng lặp. a sống lâu nhất, bị hủy sau khi main return.", "Ví dụ: Thành viên const và danh sách khởi tạo": "maSo là const: chỉ nhận giá trị một lần, ở danh sách khởi tạo. Gán maSo = m trong thân hàm sẽ là lỗi biên dịch. Các thành viên được khởi tạo đúng thứ tự khai báo: maSo, ten, diem.", "Ví dụ: Hàm hủy trả bộ nhớ (RAII)": "Hàm tạo xin khối 4 ô trên heap, hàm hủy trả lại. Người dùng lớp không phải nhớ delete: khi m hết đời sống ở cuối main, hàm hủy tự chạy và cột Heap cho thấy khối đã được trả. Không có rò rỉ.", "Ví dụ: Hàm tạo sao chép": "Diem b = a và lời gọi inBanSao(a) đều gọi hàm tạo sao chép; bản sao trong inBanSao bị hủy khi hàm kết thúc. inThamChieu không chép gì. g++ cảnh báo tham số d không dùng tới.", "Lỗi: không còn hàm tạo mặc định": "Lớp đã có hàm tạo PhanSo(int, int) nên trình biên dịch không tự sinh PhanSo() nữa: g++ báo no matching function for call to 'PhanSo::PhanSo()'. Sửa: viết thêm PhanSo() : tu(0), mau(1) {} hoặc cho tham số giá trị mặc định.", "Lỗi: sao chép nông con trỏ": "m2 = m1 dùng hàm tạo sao chép tự sinh: chép con trỏ a, nên cả hai cùng trỏ khối #1. Cuối main, m2 bị hủy trước và delete[] khối #1; rồi m1 delete[] lần nữa: free(): double free detected. Sửa bằng hàm tạo sao chép tự viết xin khối mới, hoặc dùng vector<int> thay cho int*."};EX_HINTS["l31"]=[["p / 60 là số giờ dồn sang, p % 60 là số phút còn lại; giờ mới lấy % 24.", "In 03 thay vì 3: nếu nhỏ hơn 10 thì in thêm ký tự '0' phía trước."], ["ucln(0, m) = |m|, nên 0/7 rút gọn thành 0/1 và in ra 0.", "Sau khi rút gọn, nếu mẫu âm thì đổi dấu cả tử và mẫu."], ["Sức chứa q là đủ vì có tối đa q lệnh push.", "Hàm hủy delete[] a; chạy tự động khi s hết phạm vi ở cuối main."]];
