const P31=[{label:"Ví dụ: Hàm tạo bảo đảm đối tượng hợp lệ",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass PhanSo {\n    int tu, mau;\npublic:\n    PhanSo() : tu(0), mau(1) {}\n    PhanSo(int t, int m) : tu(t), mau(m) {\n        if (mau == 0) mau = 1;\n        if (mau < 0) {\n            tu = -tu;\n            mau = -mau;\n        }\n    }\n    void in() const {\n        cout << tu << \"/\" << mau << \"\\n\";\n    }\n};\n\nint main() {\n    PhanSo a;\n    PhanSo b(3, -4);\n    PhanSo c{5, 0};\n    a.in();\n    b.in();\n    c.in();\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Thứ tự gọi hàm tạo và hàm hủy",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass Den {\n    string ten;\npublic:\n    Den(string t) : ten(t) {\n        cout << \"Bat \" << ten << \"\\n\";\n    }\n    ~Den() {\n        cout << \"Tat \" << ten << \"\\n\";\n    }\n};\n\nint main() {\n    Den a(\"phong khach\");\n    {\n        Den b(\"bep\");\n        Den c(\"san\");\n        cout << \"-- het khoi --\\n\";\n    }\n    for (int i = 1; i <= 2; i++) {\n        Den d(\"vong lap \" + to_string(i));\n    }\n    cout << \"-- het main --\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Thành viên const và danh sách khởi tạo",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass SinhVien {\n    const int maSo;\n    string ten;\n    double diem;\npublic:\n    SinhVien(int m, string t) : maSo(m), ten(t), diem(0) {}\n    void chamDiem(double d) {\n        diem = d;\n    }\n    void in() const {\n        cout << maSo << \" \" << ten << \" \" << diem << \"\\n\";\n    }\n};\n\nint main() {\n    SinhVien s(1001, \"An\");\n    s.chamDiem(8.5);\n    s.in();\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Hàm hủy trả bộ nhớ (RAII)",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass MangDong {\n    int* a;\n    int n;\npublic:\n    MangDong(int k) : a(new int[k]), n(k) {\n        for (int i = 0; i < n; i++) a[i] = i * i;\n        cout << \"Cap \" << n << \" o\\n\";\n    }\n    ~MangDong() {\n        delete[] a;\n        cout << \"Tra \" << n << \" o\\n\";\n    }\n    int tong() const {\n        int s = 0;\n        for (int i = 0; i < n; i++) s += a[i];\n        return s;\n    }\n};\n\nint main() {\n    MangDong m(4);\n    cout << m.tong() << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Hàm tạo sao chép",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass Diem {\n    int x, y;\npublic:\n    Diem(int a, int b) : x(a), y(b) {\n        cout << \"Tao (\" << x << \",\" << y << \")\\n\";\n    }\n    Diem(const Diem& k) : x(k.x), y(k.y) {\n        cout << \"Chep (\" << x << \",\" << y << \")\\n\";\n    }\n    ~Diem() {\n        cout << \"Huy (\" << x << \",\" << y << \")\\n\";\n    }\n};\n\nvoid inBanSao(Diem d) {\n    cout << \"Trong ham\\n\";\n}\n\nvoid inThamChieu(const Diem& d) {\n    cout << \"Tham chieu\\n\";\n}\n\nint main() {\n    Diem a(1, 2);\n    Diem b = a;\n    inBanSao(a);\n    inThamChieu(a);\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Lỗi: không còn hàm tạo mặc định",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass PhanSo {\n    int tu, mau;\npublic:\n    PhanSo(int t, int m) : tu(t), mau(m) {}\n};\n\nint main() {\n    PhanSo p;\n    return 0;\n}"},{label:"Lỗi: sao chép nông con trỏ",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass MangDong {\n    int* a;\npublic:\n    MangDong(int k) : a(new int[k]) {}\n    ~MangDong() {\n        delete[] a;\n    }\n};\n\nint main() {\n    MangDong m1(3);\n    MangDong m2 = m1;\n    cout << \"Sap ket thuc\\n\";\n    return 0;\n}",viz:[{type:"mem"}]}];
