makeEx2(document.getElementById("ex-l31"),sim31,[{t:"Lớp ThoiGian",d:"Viết lớp <code>ThoiGian<\/code> có hai thành viên private giờ, phút và hàm tạo <code>ThoiGian(int g, int p)<\/code> chuẩn hóa: phút ≥ 60 thì dồn sang giờ, giờ lấy theo 24 (0 ≤ g, p ≤ 10<sup>6<\/sup>). Hàm thành viên <code>void in() const<\/code> in dạng HH:MM. Nhập g p, tạo đối tượng và in.",tests:[{in:"1 130",out:"03:10"},{in:"23 60",out:"00:00"},{in:"0 5",out:"00:05"},{in:"48 1439",out:"23:59"}],start:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass ThoiGian {\n    int gio, phut;\npublic:\n    ThoiGian(int g, int p) {\n        // chuẩn hóa: dồn phút sang giờ, giờ theo 24\n    }\n    void in() const {\n        // in hai chữ số: thêm '0' phía trước nếu nhỏ hơn 10\n    }\n};\n\nint main() {\n    int g, p;\n    cin >> g >> p;\n    ThoiGian t(g, p);\n    t.in();\n    return 0;\n}",need:/class\s+ThoiGian[\s\S]*ThoiGian\s*\(\s*int\s+\w+\s*,\s*int\s+\w+\s*\)[\s\S]*void\s+in\s*\(\s*\)\s*const/,needMsg:"Hãy giữ lớp ThoiGian với hàm tạo ThoiGian(int, int) và hàm void in() const."},{t:"Phân số tối giản",d:"Viết lớp <code>PhanSo<\/code> có hàm tạo <code>PhanSo(int t, int m)<\/code> tự rút gọn (chia cho ước chung lớn nhất) và đưa dấu âm lên tử. Hàm <code>void in() const<\/code> in <code>t/m<\/code>, hoặc chỉ <code>t<\/code> nếu mẫu bằng 1. Nhập t m (m ≠ 0, |t|, |m| ≤ 10<sup>9<\/sup>).",tests:[{in:"6 -8",out:"-3/4"},{in:"10 5",out:"2"},{in:"0 7",out:"0"},{in:"-12 -18",out:"2/3"}],start:"#include <iostream>\n#include <string>\nusing namespace std;\n\nint ucln(int a, int b) {\n    if (a < 0) a = -a;\n    if (b < 0) b = -b;\n    while (b != 0) {\n        int r = a % b;\n        a = b;\n        b = r;\n    }\n    return a;\n}\n\nclass PhanSo {\n    int tu, mau;\npublic:\n    PhanSo(int t, int m) : tu(t), mau(m) {\n        // rút gọn bằng ucln, rồi đưa dấu âm lên tử\n    }\n    void in() const {\n        // in tu/mau, hoặc chỉ tu khi mau == 1\n    }\n};\n\nint main() {\n    int t, m;\n    cin >> t >> m;\n    PhanSo p(t, m);\n    p.in();\n    return 0;\n}",need:/class\s+PhanSo[\s\S]*PhanSo\s*\(\s*int\s+\w+\s*,\s*int\s+\w+\s*\)/,needMsg:"Hãy giữ lớp PhanSo với hàm tạo PhanSo(int t, int m)."},{t:"Ngăn xếp tự trả bộ nhớ",d:"Viết lớp <code>NganXep<\/code>: hàm tạo <code>NganXep(int cap)<\/code> xin <code>new int[cap]<\/code>, hàm hủy <code>delete[]<\/code>; các hàm <code>void day(int x)<\/code>, <code>void lay()<\/code>, <code>int dinh() const<\/code>, <code>bool rong() const<\/code>. Nhập q (1 ≤ q ≤ 1000) rồi q lệnh: <code>push x<\/code>, <code>pop<\/code> (bỏ qua nếu rỗng), <code>top<\/code> (in phần tử đỉnh, hoặc EMPTY).",tests:[{in:"6\npush 3\npush 5\ntop\npop\ntop\npop",out:"5\n3"},{in:"3\ntop\npop\ntop",out:"EMPTY\nEMPTY"},{in:"4\npush 1\npush 2\npush 3\ntop",out:"3"}],start:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass NganXep {\n    int* a;\n    int n;\npublic:\n    NganXep(int cap) : a(new int[cap]), n(0) {}\n    ~NganXep() {\n        // trả vùng nhớ\n    }\n    void day(int x) { a[n++] = x; }\n    void lay() { /* bỏ phần tử đỉnh nếu có */ }\n    int dinh() const { return a[n - 1]; }\n    bool rong() const { return n == 0; }\n};\n\nint main() {\n    int q;\n    cin >> q;\n    NganXep s(q);\n    for (int i = 0; i < q; i++) {\n        string lenh;\n        cin >> lenh;\n        // xử lý push / pop / top\n    }\n    return 0;\n}",need:/~\s*NganXep\s*\(\s*\)\s*\{[^}]*delete\s*\[\s*\]/,needMsg:"Hàm hủy ~NganXep() phải trả vùng nhớ bằng delete[] a;."}]);

makeQuiz("quiz31","score31",[{"q": "Lớp chỉ có hàm tạo <code>A(int x)<\/code>. Dòng <code>A a;<\/code> thì sao?", "o": ["a.x bằng 0", "Lỗi biên dịch: không có hàm tạo mặc định", "a.x chứa giá trị rác", "Gọi A(0)"], "a": 1, "e": "Đã tự viết một hàm tạo thì trình biên dịch không tự sinh A() nữa."}, {"q": "Trong <code>main<\/code> tạo lần lượt a, b, c (cùng phạm vi). Khi main kết thúc, hàm hủy chạy theo thứ tự nào?", "o": ["a, b, c", "c, b, a", "b, a, c", "Không chạy"], "a": 1, "e": "Đối tượng bị hủy theo thứ tự ngược với lúc tạo."}, {"q": "Thành viên <code>const int maSo;<\/code> phải được gán giá trị ở đâu?", "o": ["Trong thân hàm tạo", "Trong danh sách khởi tạo sau dấu : của hàm tạo", "Trong hàm hủy", "Ở bất kỳ hàm thành viên nào"], "a": 1, "e": "Thành viên const chỉ nhận giá trị một lần, ở danh sách khởi tạo."}, {"q": "Lớp giữ <code>int* a<\/code> trỏ tới vùng nhớ riêng, không tự viết hàm tạo sao chép. <code>B b2 = b1;<\/code> dẫn tới điều gì khi cả hai bị hủy (hàm hủy delete[] a)?", "o": ["Không có gì", "Rò rỉ bộ nhớ", "Vùng nhớ bị delete hai lần (double free)", "Lỗi biên dịch"], "a": 2, "e": "Bản sao tự sinh chép con trỏ, hai đối tượng cùng trỏ một vùng, nên vùng đó bị trả hai lần."}]);

